-- Neue Spielerbilder vom Icon League Mediaday (154 Spieler). Zuordnung über icon_slug.
-- Komplett im Supabase SQL Editor ausführen (bei Nachfrage "Run without RLS"). Mehrfach ausführbar.
create temp table img_in (icon_slug text, url text);

update players p set image_url = i.url
from img_in i
where p.external_refs->>'icon_slug' = i.icon_slug
  and p.image_url is distinct from i.url
  and exists (select 1 from season_players sp join seasons s on s.id = sp.season_id
              where sp.player_id = p.id and s.slug = 'season-5');

-- Kontrolle
select 'Spieler Season 5' as info, count(*)::text as wert
from season_players sp join seasons s on s.id = sp.season_id where s.slug = 'season-5'
union all
select 'davon mit neuem Mediaday-Bild', count(*)::text
from season_players sp join seasons s on s.id = sp.season_id join players p on p.id = sp.player_id
join img_in i on i.url = p.image_url where s.slug = 'season-5'
union all
select 'ohne neues Bild: ' || c.short_name, p.display_name
from season_players sp join seasons s on s.id = sp.season_id join players p on p.id = sp.player_id
join season_teams st on st.id = sp.season_team_id join clubs c on c.id = st.club_id
where s.slug = 'season-5' and not exists (select 1 from img_in i where i.url = p.image_url);
drop table img_in;
